import { test, expect } from '@playwright/test';

test.describe('Interactive Toast Notifications - Screen Reader Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/toast-notifications');
  });

  test('should announce toast notification content to screen readers when displayed', async ({ page }) => {
    // Verify toast container is visible
    const toastContainer = page.getByRole('region', { name: /toast container/i });
    await expect(toastContainer).toBeVisible();

    // Click button to trigger toast
    const triggerButton = page.getByRole('button', { name: /show toast/i });
    await triggerButton.click();

    // Wait for toast to appear
    const toast = page.getByRole('alert');
    await expect(toast).toBeVisible();

    // Verify toast content is announced
    const toastMessage = page.getByText(/success/i);
    await expect(toastMessage).toBeVisible();

    // Verify toast has appropriate aria-live region
    const liveRegion = page.locator('[aria-live="polite"]');
    await expect(liveRegion).toBeVisible();

    // Verify toast has role="alert"
    await expect(toast).toHaveAttribute('role', 'alert');

    // Verify toast has appropriate aria-describedby
    const toastId = await toast.getAttribute('id');
    const describedBy = page.locator(`[aria-describedby="${toastId}"]`);
    await expect(describedBy).toBeVisible();
  });

  test('should dismiss toast notification and announce dismissal to screen readers', async ({ page }) => {
    // Click button to trigger toast
    const triggerButton = page.getByRole('button', { name: /show toast/i });
    await triggerButton.click();

    // Wait for toast to appear
    const toast = page.getByRole('alert');
    await expect(toast).toBeVisible();

    // Verify toast content is visible
    const toastMessage = page.getByText(/success/i);
    await expect(toastMessage).toBeVisible();

    // Click close button on toast
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Wait for toast to dismiss
    await page.waitForTimeout(500);

    // Verify toast is no longer visible
    await expect(toast).not.toBeVisible();

    // Verify toast container is still present
    const toastContainer = page.getByRole('region', { name: /toast container/i });
    await expect(toastContainer).toBeVisible();

    // Verify aria-live region is still present
    const liveRegion = page.locator('[aria-live="polite"]');
    await expect(liveRegion).toBeVisible();
  });
});
